import React from "react"

import Panel from "../layout/Panel"
import { Badge, Delta } from "../ui"

/**
 * The /technical right rail: key figures, signal verdicts and a price ladder.
 *
 * Everything rendered here is READ from props. The page computes getIndicators,
 * getSignals and getSessionChange once and hands the same objects to the chart
 * and to this rail, so a number in the list can never disagree with the line
 * drawn next to it.
 *
 * Null discipline: every indicator array in the data layer is null-padded, and
 * a short series (a 5-bar "5D") genuinely has no EMA 20, EMA 50, RSI or MACD.
 * Each formatter below returns an em dash for anything that is not a finite
 * number, so nothing can reach the DOM as NaN, null, undefined or Infinity.
 *
 * Pure render — no window, document or storage — so Gatsby's Node build renders
 * it identically to the browser.
 */

const DASH = "—"

function isNum(value) {
  return value !== null && value !== undefined && Number.isFinite(value)
}

/** Money. Always carries the leading dollar sign the contract asks for. */
function usd(value, digits = 2) {
  return isNum(value) ? "$" + value.toFixed(digits) : DASH
}

/** A bare decimal — for readings that are not prices (RSI, MACD). */
function fixed(value, digits) {
  return isNum(value) ? value.toFixed(digits) : DASH
}

/** 70,612,400 -> "70.6M". Keeps a volume column narrow and scannable. */
function compact(value) {
  if (!isNum(value)) return DASH
  const abs = Math.abs(value)
  if (abs >= 1e12) return (value / 1e12).toFixed(2) + "T"
  if (abs >= 1e9) return (value / 1e9).toFixed(1) + "B"
  if (abs >= 1e6) return (value / 1e6).toFixed(1) + "M"
  if (abs >= 1e3) return (value / 1e3).toFixed(1) + "K"
  return String(Math.round(value))
}

/** Total traded volume across the visible series. Null when nothing is finite. */
function sumVolume(candles) {
  let total = 0
  let seen = false
  for (let i = 0; i < candles.length; i += 1) {
    const candle = candles[i]
    if (candle && isNum(candle.volume)) {
      total += candle.volume
      seen = true
    }
  }
  return seen ? total : null
}

/**
 * Relative volume: this series' total against the company's average daily
 * volume. A zero, negative or missing average is not a ratio — it is a dash.
 */
function relativeVolume(total, average) {
  if (!isNum(total) || !isNum(average) || average <= 0) return DASH
  const value = total / average
  return isNum(value) ? value.toFixed(2) + "x" : DASH
}

/**
 * Where a level sits inside the 52-week range, as a 0-100 percentage.
 * Returns null — meaning "draw no marker" — for a missing level or a range
 * that is zero or inverted.
 */
function offsetPct(level, low, high) {
  if (!isNum(level) || !isNum(low) || !isNum(high)) return null
  const range = high - low
  if (!(range > 0)) return null
  const pct = ((level - low) / range) * 100
  if (!Number.isFinite(pct)) return null
  // Rounded to two places so the serialised style attribute reads "70.82%"
  // rather than a floating-point tail like "70.82018927444793%".
  return Math.round(Math.max(0, Math.min(100, pct)) * 100) / 100
}

const TONE_BY_VERDICT = {
  Bullish: "bullish",
  Bearish: "bearish",
  Neutral: "neutral",
}

/** Top to bottom: highest resistance first, so the ladder reads like a chart. */
const LEVEL_ROWS = [
  { key: "r2", name: "Resistance 2", modifier: "level--r2" },
  { key: "r1", name: "Resistance 1", modifier: "level--r1" },
  { key: "s1", name: "Support 1", modifier: "level--s1" },
  { key: "s2", name: "Support 2", modifier: "level--s2" },
]

export default function RightRail({ company, data, signals, change }) {
  const profile = company || {}
  const latest = (data && data.latest) || {}
  const candles = (data && data.candles) || []
  const session = change || {}
  const signalRows = (signals && signals.signals) || []
  const levels = (signals && signals.levels) || {}

  const previous = candles.length >= 2 ? candles[candles.length - 2] : null
  const totalVolume = sumVolume(candles)
  const low52 = profile.week52Low
  const high52 = profile.week52High

  const direction = session.direction === "up" || session.direction === "down"
    ? session.direction
    : null

  /*
   * The key-data rows, in the fixed contract order. Each entry carries either a
   * pre-formatted string or a node; the Change row is the only coloured value.
   */
  const keyRows = [
    { key: "price", label: "Price", value: usd(latest.close) },
    {
      key: "change",
      label: "Change",
      modifier: direction ? "kv__value--" + direction : null,
      node: <Delta value={isNum(session.changePct) ? session.changePct : null} percent />,
    },
    { key: "volume", label: "Volume", value: compact(totalVolume) },
    {
      key: "rvol",
      label: "RVOL",
      hint: "Session volume against the company's average daily volume",
      value: relativeVolume(totalVolume, profile.avgVolume),
    },
    { key: "vwap", label: "VWAP", value: usd(latest.vwap) },
    { key: "ema9", label: "EMA 9", value: usd(latest.ema9) },
    { key: "ema20", label: "EMA 20", value: usd(latest.ema20) },
    { key: "ema50", label: "EMA 50", value: usd(latest.ema50) },
    { key: "ema200", label: "EMA 200", value: usd(latest.ema200) },
    { key: "rsi14", label: "RSI (14)", value: fixed(latest.rsi14, 1) },
    { key: "macd", label: "MACD", value: fixed(latest.macdHistogram, 4) },
    {
      key: "prevHigh",
      label: "Previous high",
      value: previous ? usd(previous.high) : DASH,
    },
    {
      key: "prevLow",
      label: "Previous low",
      value: previous ? usd(previous.low) : DASH,
    },
    { key: "high52", label: "52-week high", value: usd(high52) },
    { key: "low52", label: "52-week low", value: usd(low52) },
  ]

  return (
    <>
      <Panel title="Key technical data">
        <div className="kv">
          {keyRows.map(row => (
            <div className="kv__row" key={row.key}>
              <span className="kv__label" title={row.hint || undefined}>
                {row.label}
              </span>
              <span className={["kv__value", row.modifier].filter(Boolean).join(" ")}>
                {row.node || row.value}
              </span>
            </div>
          ))}
        </div>
      </Panel>

      <Panel title="Technical signals">
        {signalRows.length === 0 ? (
          <p className="empty__text">No signals for this timeframe yet.</p>
        ) : (
          <ul className="signal-list">
            {signalRows.map(signal => (
              <li className="signal-row" key={signal.key}>
                <span className="signal-row__text">
                  <span className="signal-row__label">{signal.label}</span>
                  <span className="signal-row__value">{signal.value || DASH}</span>
                </span>
                <Badge tone={TONE_BY_VERDICT[signal.verdict] || "neutral"}>
                  {signal.verdict || "Neutral"}
                </Badge>
              </li>
            ))}
          </ul>
        )}
      </Panel>

      <Panel title="Support & resistance">
        <ul className="levels">
          {LEVEL_ROWS.map(row => {
            const level = levels[row.key]
            const pct = offsetPct(level, low52, high52)

            return (
              <li className={"level " + row.modifier} key={row.key}>
                <div className="level__head">
                  <span className="level__name">{row.name}</span>
                  <span className="level__price">{usd(level)}</span>
                </div>
                <div className="level__track" aria-hidden="true">
                  {pct !== null && (
                    <span className="level__marker" style={{ left: pct + "%" }} />
                  )}
                </div>
              </li>
            )
          })}
        </ul>

        <div className="levels__scale" title="52-week range">
          <span className="levels__scale-end">{usd(low52)}</span>
          <span className="levels__scale-end">{usd(high52)}</span>
        </div>
      </Panel>
    </>
  )
}
