import React, { useMemo, useState } from "react"

import Shell from "../components/layout/Shell"
import Panel from "../components/layout/Panel"
import Breadcrumb from "../components/ui/Breadcrumb"
import TickerMark from "../components/ui/TickerMark"
import Delta from "../components/ui/Delta"

import LeftRail from "../components/technical/LeftRail"
import RightRail from "../components/technical/RightRail"
import ChartStack from "../components/technical/ChartStack"
import { buildView, defaultIndicators } from "../components/technical/series"
import { intervalOptions, resolveInterval } from "../data/candles"
import { DEFAULT_INTERVAL, isIntradayInterval } from "../data/aggregate"

import { getCompany } from "../data/companies"
import { getSignals } from "../data/signals"
import { getSessionChange } from "../data/markets"

/* -------------------------------------------------------------------------- */

const usd = (n, d = 2) => (n === null || !Number.isFinite(n) ? "—" : "$" + n.toFixed(d))

function compact(n) {
  if (n === null || !Number.isFinite(n)) return "—"
  const a = Math.abs(n)
  if (a >= 1e12) return (n / 1e12).toFixed(2) + "T"
  if (a >= 1e9) return (n / 1e9).toFixed(2) + "B"
  if (a >= 1e6) return (n / 1e6).toFixed(1) + "M"
  if (a >= 1e3) return (n / 1e3).toFixed(1) + "K"
  return String(Math.round(n))
}

function QuoteStat({ label, value }) {
  return (
    <div className="quote-stat">
      <span className="quote-stat__label">{label}</span>
      <span className="quote-stat__value">{value}</span>
    </div>
  )
}

/* -------------------------------------------------------------------------- */

export default function TechnicalPage({ location }) {
  const [symbol, setSymbol] = useState("AAPL")
  const [timeframe, setTimeframe] = useState("1D")
  /*
   * SMT-003. Timeframe and interval are INDEPENDENT state: one says how much
   * history, the other how it is chopped up. The only coupling is that not
   * every pair can be served from the data we hold — resolveInterval keeps the
   * selection on a combination that exists rather than leaving the chart blank
   * when the timeframe changes underneath it.
   */
  const [intervalPref, setIntervalPref] = useState(DEFAULT_INTERVAL)
  const [chartStyle, setChartStyle] = useState("candlestick")
  const [indicators, setIndicators] = useState(defaultIndicators)

  // `nonce` only exists so the "Update chart" button can force a remount of the
  // chart. Every control already applies immediately — see the note on the
  // button in LeftRail.
  const [nonce, setNonce] = useState(0)

  const company = getCompany(symbol)

  // ONE computation feeds the chart, the legend and the right rail, so nothing
  // on the page can contradict the line that is drawn.
  const intervals = useMemo(() => intervalOptions(symbol, timeframe), [symbol, timeframe])
  const interval = useMemo(
    () => resolveInterval(symbol, timeframe, intervalPref),
    [symbol, timeframe, intervalPref]
  )
  /* Says plainly why a choice is unavailable, instead of a greyed-out button. */
  const intervalNote = useMemo(() => {
    if (intervalPref === interval) return null
    const asked = intervals.find(i => i.key === intervalPref)
    return asked && asked.reason ? asked.reason + " Showing " + interval + " instead." : null
  }, [intervals, intervalPref, interval])

  const view = useMemo(
    () => buildView(symbol, timeframe, indicators, interval),
    [symbol, timeframe, indicators, interval]
  )
  const signals = useMemo(() => getSignals(symbol, timeframe), [symbol, timeframe])
  const change = useMemo(() => getSessionChange(symbol), [symbol])

  const { stats, overlays } = view
  const price = view.data.latest.close

  return (
    <Shell location={location}>
      <div className="page">
        <div className="page__breadcrumb">
          <Breadcrumb
            items={[{ label: "Home", to: "/" }, { label: "Technical analysis" }]}
          />
        </div>

        <header className="page__head">
          <div className="page__heading">
            <h1 className="page__title">Technical analysis</h1>
            <p className="page__lede">
              Price action, indicators and trading activity in one view.
            </p>
          </div>
        </header>

        <div className="tech">
          {/* ---------------- Left rail ---------------- */}
          <div className="tech__rail-left">
            <div className="tech__sticky">
              <LeftRail
                symbol={symbol}
                onSymbolChange={setSymbol}
                timeframe={timeframe}
                onTimeframeChange={setTimeframe}
                interval={interval}
                intervals={intervals}
                intervalNote={intervalNote}
                onIntervalChange={setIntervalPref}
                indicators={indicators}
                onIndicatorsChange={setIndicators}
                chartStyle={chartStyle}
                onChartStyleChange={setChartStyle}
                onUpdate={() => setNonce(n => n + 1)}
              />
            </div>
          </div>

          {/* ---------------- Centre ---------------- */}
          <div className="tech__center">
            <div className="quote-bar">
              <div className="quote-bar__main">
                <div className="quote-bar__identity">
                  <TickerMark symbol={symbol} size={44} />
                  <div className="quote-bar__text">
                    <span className="quote-bar__symbol">{symbol}</span>
                    <span className="quote-bar__name">
                      {company.name} · {company.exchange}
                    </span>
                  </div>
                </div>
                <div className="quote-bar__price-row">
                  <span className="quote-bar__price">{usd(price)}</span>
                  <Delta value={change.changeAbs} digits={2} size="lg" showGlyph={false} />
                  <Delta value={change.changePct} percent digits={2} size="lg" />
                </div>
              </div>

              <div className="quote-bar__stats">
                <QuoteStat label="Open" value={usd(stats.open)} />
                <QuoteStat label="High" value={usd(stats.high)} />
                <QuoteStat label="Low" value={usd(stats.low)} />
                <QuoteStat label="Volume" value={compact(stats.volume)} />
                <QuoteStat label="Market cap" value={compact(company.marketCap)} />
              </div>
            </div>

            <Panel flush divided={false}>
              <div className="chart-legend">
                <span className="chart-legend__chip">
                  <span className="chart-legend__swatch chart-legend__swatch--candles" />
                  <span className="chart-legend__name">{symbol}</span>
                  <span className="chart-legend__value">{usd(price)}</span>
                </span>

                {overlays.map(overlay => (
                  <span className="chart-legend__chip" key={overlay.key}>
                    <span
                      className="chart-legend__swatch"
                      style={{ background: "var(" + overlay.token + ")" }}
                    />
                    <span className="chart-legend__name">{overlay.label}</span>
                    <span
                      className="chart-legend__value"
                      style={{ color: "var(" + overlay.token + ")" }}
                    >
                      {overlay.latest === null ? "—" : overlay.latest.toFixed(overlay.digits)}
                    </span>
                  </span>
                ))}

                {overlays.length === 0 && (
                  <span className="chart-legend__empty">
                    No overlays selected — turn one on in the left rail.
                  </span>
                )}
              </div>

              <ChartStack
                key={
                  symbol + "|" + timeframe + "|" + interval + "|" + chartStyle + "|" + nonce
                }
                view={view}
                chartStyle={chartStyle}
                intraday={isIntradayInterval(interval)}
              />
            </Panel>
          </div>

          {/* ---------------- Right rail ---------------- */}
          <div className="tech__rail-right">
            <div className="tech__rail-stack">
              <RightRail
                company={company}
                data={view.data}
                signals={signals}
                change={change}
              />
            </div>
          </div>
        </div>
      </div>
    </Shell>
  )
}

export const Head = () => <title>Technical analysis · MarketScan</title>
