import { getIndicators, ema } from "../../data/indicators.js"

/**
 * Builds everything the /technical centre column needs from ONE call into the
 * data layer.
 *
 * The chart and the legend chips read the same `overlays` array, and the right
 * rail is handed the same `data` object, so a number shown anywhere on the page
 * is by construction the number plotted on the chart. That is the whole point:
 * there is no second calculation for anything to disagree with.
 */

/** The period each EMA slot uses unless the user changes it via its gear popover. */
export const DEFAULT_EMA_PERIODS = { ema9: 9, ema20: 20, ema50: 50, ema200: 200 }

export const EMA_KEYS = ["ema9", "ema20", "ema50", "ema200"]

/** The starting indicator configuration: volume, VWAP, EMA 9/20, RSI and MACD on. */
export function defaultIndicators() {
  return {
    volume: true,
    vwap: true,
    ema9: { on: true, period: 9 },
    ema20: { on: true, period: 20 },
    ema50: { on: false, period: 50 },
    ema200: { on: false, period: 200 },
    rsi: true,
    macd: true,
  }
}

function last(array) {
  if (!Array.isArray(array) || !array.length) return null
  const value = array[array.length - 1]
  return value === undefined ? null : value
}

export function buildView(symbol, timeframe, config, interval) {
  const data = getIndicators(symbol, timeframe, interval)
  const { candles, closes } = data

  const overlays = []

  if (config.vwap) {
    /*
     * The legend says WHICH VWAP it is. On intraday bars that is the session
     * VWAP; on a daily series it is the 20-bar rolling figure, because a
     * session VWAP there is just the bar's own price. Labelling both plainly
     * "VWAP" invites the reader to compare two different measures across a
     * timeframe switch and conclude the level moved when the definition did.
     */
    overlays.push({
      key: "vwap",
      label: data.vwapKind === "rolling-20" ? "VWAP 20" : "VWAP",
      token: "--chart-vwap",
      values: data.vwap,
      latest: last(data.vwap),
      digits: 2,
    })
  }

  for (const key of EMA_KEYS) {
    const slot = config[key]
    if (!slot || !slot.on) continue
    // Reuse the precomputed array when the period is untouched; only recompute
    // when the user has actually changed it in the gear popover.
    const values =
      slot.period === DEFAULT_EMA_PERIODS[key] ? data[key] : ema(closes, slot.period)
    overlays.push({
      key,
      label: "EMA " + slot.period,
      token: "--chart-" + key,
      values,
      latest: last(values),
      digits: 2,
    })
  }

  let high = null
  let low = null
  let volume = 0
  for (const c of candles) {
    if (high === null || c.high > high) high = c.high
    if (low === null || c.low < low) low = c.low
    volume += c.volume
  }

  return {
    data,
    candles,
    overlays,
    rsi: data.rsi14,
    macd: data.macd,
    showVolume: Boolean(config.volume),
    showRsi: Boolean(config.rsi),
    showMacd: Boolean(config.macd),
    stats: {
      open: candles.length ? candles[0].open : null,
      high,
      low,
      volume,
      close: data.latest.close,
    },
  }
}
